import numpy as np
from scipy.spatial.distance import cdist
from sklearn.cluster import KMeans

class ACDE:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim
        self.population_size = 10 * dim
        self.F_range = (0.4, 1.0)
