        if np.random.rand() < 0.5:
            return np.clip(best + F * (r1 - r2), self.bounds.lb, self.bounds.ub)
        else:
            return np.clip(target + F * (best - target) + F * (r1 - r2), self.bounds.lb, self.bounds.ub)

    def crossover(self, target, mutant, CR):
